bool vega_east_asian(uint32_t code) {
    size_t low = 0, high = sizeof(east_asian) / sizeof(*east_asian);
    while (low < high) {
        size_t middle = (low + high) / 2;
        if (east_asian[middle][1] < code) low = middle + 1;
        else high = middle;
    }
    return low < sizeof(east_asian) / sizeof(*east_asian) && east_asian[low][0] <= code;
}

