size_t vega_decomposition(uint32_t code, const uint32_t **out) {
    long row = find(&decompositions[0][0], sizeof(decompositions) / sizeof(*decompositions), 3, code);
    if (row < 0) return 0;
    *out = decomposed + decompositions[row][1];
    return decompositions[row][2];
}

