bool vega_decomposition_step(uint32_t code, uint32_t *first, uint32_t *second) {
    long row = find(&steps[0][0], sizeof(steps) / sizeof(*steps), 3, code);
    if (row < 0) return false;
    *first = steps[row][1];
    *second = steps[row][2];
    return true;
}

